const net = require('net')
const Fastify = require('/tmp/cxbench/8b9c07b645-hooks/fastify')

async function main () {
  let hookCalls = 0
  const fastify = Fastify({ connectionTimeout: 400 })
  fastify.addHook('onTimeout', (req, reply, done) => { hookCalls++; done() })

  let seenSocket = null
  fastify.get('/', async (req, reply) => {
    seenSocket = req.raw.socket
    return reply.send({ hello: 'world' })
  })
  fastify.get('/timeout', async (req, reply) => reply)

  const url = await fastify.listen({ port: 0 })
  const port = new URL(url).port

  // two keep-alive requests on ONE socket
  const socket = net.connect(port, '127.0.0.1')
  await new Promise(r => socket.once('connect', r))
  const request = (path) => new Promise(resolve => {
    let buf = ''
    const onData = d => {
      buf += d
      if (buf.includes('\r\n\r\n') && /world|}/.test(buf)) { socket.off('data', onData); resolve(buf) }
    }
    socket.on('data', onData)
    socket.write(`GET ${path} HTTP/1.1\r\nHost: x\r\nConnection: keep-alive\r\n\r\n`)
  })

  await request('/')
  await new Promise(r => setImmediate(r))
  console.log('after 1st response, _meta:', seenSocket._meta)
  console.log('timeout listeners:', seenSocket.listenerCount('timeout'))

  await request('/')
  await new Promise(r => setImmediate(r))
  console.log('after 2nd response, _meta:', seenSocket._meta)
  console.log('timeout listeners:', seenSocket.listenerCount('timeout'))

  // now let the idle keep-alive socket time out: must not throw, must not run hooks
  await new Promise(r => setTimeout(r, 700))
  console.log('idle timeout -> hook calls (expect 0):', hookCalls)

  // a request that never responds must still fire onTimeout exactly once
  const s2 = net.connect(port, '127.0.0.1')
  await new Promise(r => s2.once('connect', r))
  s2.write('GET /timeout HTTP/1.1\r\nHost: x\r\nConnection: keep-alive\r\n\r\n')
  await new Promise(r => setTimeout(r, 900))
  console.log('in-flight timeout -> hook calls (expect 1):', hookCalls)

  socket.destroy(); s2.destroy()
  await fastify.close()
}
